            "content": "def transform(grid):\n    out=[row[:] for row in grid]\n    h,w=len(grid),len(grid[0])\n    bg=max(set(v for row in grid for v in row),key=lambda v:sum(x==v for row in grid for x in row))\n    # Fill only a complete rectangular outline object (all perimeter cells\n    # same non-background color, empty interior), not incidental rectangles.\n    fills={9:7,0:7,1:2,3:7,5:7,6:2,8:7}\n    for r0 in range(h):\n        for r1 in range(r0+2,h):\n            for c0 in range(w):\n                for c1 in range(c0+2,w):\n                    color=grid[r0][c0]\n                    if color==bg or color not in fills: continue\n                    if (all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and\n                        all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1)) and\n                        all(grid[r][c]==bg for r in range(r0+1,r1) for c in range(c0+1,c1))):\n                        for r in range(r0+1,r1):\n                            for c in range(c0+1,c1): out[r][c]=fills[color]\n    # Fill the central background cell in the small 3x3 motif objects.\n    for r in range(1,h-1):\n        for c in range(1,w-1):\n            col=grid[r][c]\n            if col==bg and grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1] and grid[r-1][c]!=bg:\n                out[r][c]=7\n    return out\n"
