 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    bg=max({v for row in grid for v in row},key=lambda v:sum(x==v for row in grid for x in row))
    seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                y,x=stack.pop(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in pts); r1=max(y for y,x in pts)
            c0=min(x for y,x in pts); c1=max(x for y,x in pts)
            if r1-r0<2 or c1-c0<2: continue
            if (all(grid[r0][x]==color and grid[r1][x]==color for x in range(c0,c1+1)) and
                all(grid[y][c0]==color and grid[y][c1]==color for y in range(r0,r1+1)) and
                all(grid[y][x]==bg for y in range(r0+1,r1) for x in range(c0+1,c1))):
                fill=7 if ((r1-r0-1)*(c1-c0-1))%2 else 2
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1): out[y][x]=fill
    # Small cross motifs have a single missing center, filled with 7.
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==bg and grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1]!=bg:
                out[r][c]=7
    return out
